db.products.insertOne({ name: "Caneca", price: 29.9, tags: ["cozinha"], stock: 10 });

db.products.find(
  { price: { $lt: 50 }, tags: "cozinha" },
  { name: 1, price: 1 },
).sort({ price: 1 });

db.products.updateOne({ name: "Caneca" }, { $inc: { stock: -1 }, $set: { updatedAt: new Date() } });

db.createCollection("products", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["name", "price"],
      properties: {
        name: { bsonType: "string", minLength: 1 },
        price: { bsonType: ["double", "decimal"], minimum: 0 },
      },
    },
  },
});

// pedidos
{
  _id: ObjectId("..."),
  customerId: ObjectId("..."),     // referência
  customerName: "Ana Souza",         // cópia para listagem
  items: [                           // embutidos
    { productId: ObjectId("..."), name: "Caneca", quantity: 2, unitPrice: 29.9 }
  ],
  total: 59.8,
  createdAt: ISODate("2026-10-05T12:00:00Z")
}

db.readings.updateOne(
  { sensorId: "s-1", hour: ISODate("2026-10-05T12:00:00Z") },
  {
    $push: { values: { at: new Date(), temp: 22.4 } },
    $inc: { count: 1 },
  },
  { upsert: true },
);

db.orders.aggregate([
  { $match: { status: "paid", createdAt: { $gte: ISODate("2026-10-01") } } },
  { $unwind: "$items" },
  {
    $group: {
      _id: "$items.category",
      revenue: { $sum: { $multiply: ["$items.quantity", "$items.unitPrice"] } },
    },
  },
  { $sort: { revenue: -1 } },
]);

db.orders.createIndex({ status: 1, createdAt: -1, total: 1 });

db.orders
  .find({ status: "paid", total: { $gt: 100 } })
  .sort({ createdAt: -1 })
  .explain("executionStats");
